Lemma geo_1RB1LC_1LA1RD_1RB1LC_0LC0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_1LA1RD_1RB1LC_0LC0RB) = lift (Cc (Pos.succ p)).
