Definition mk_1RB1LC_1LC1RB_0RB1LD_0RA0LC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1LC_1LC1RB_0RB1LD_0RA0LC.

(** 1RB1LC_1LC1RB_0RB1LD_0RA0LC *)
(** 1RB1LC_1LC1RB_0RB1LD_0RA0LC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1LC_1LC1RB_0RB1LD_0RA0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S0 DL StC end.

(** Its mirror 1LB1RC_1RC1LB_0LB1RD_0LA0RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LC_1LC1RB_0RB1LD_0RA0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LC_1LC1RB_0RB1LD_0RA0LC : list Instr := [(StA, S0)].
Definition tmw_1RB1LC_1LC1RB_0RB1LD_0RA0LC : TM := tm_wrap_trs tmm_1RB1LC_1LC1RB_0RB1LD_0RA0LC pins_1RB1LC_1LC1RB_0RB1LD_0RA0LC.
Local Notation tm := tmw_1RB1LC_1LC1RB_0RB1LD_0RA0LC.

Lemma mirror_ok_1RB1LC_1LC1RB_0RB1LD_0RA0LC : mirror_tm tm_1RB1LC_1LC1RB_0RB1LD_0RA0LC = tmm_1RB1LC_1LC1RB_0RB1LD_0RA0LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

