(** ** The lap *)

Lemma lap_1RB1LC_1RC0RD_1LA0RD_0LA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_1RC0RD_1LA0RD_0LA1RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_1RC0RD_1LA0RD_0LA1RD B0_1RB1LC_1RC0RD_1LA0RD_0LA1RD B1_1RB1LC_1RC0RD_1LA0RD_0LA1RD 4 10 p j' [] []).
    + exact run_ovf_1RB1LC_1RC0RD_1LA0RD_0LA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1RC0RD_1LA0RD_0LA1RD p j' E).
    + exact (geo_1RB1LC_1RC0RD_1LA0RD_0LA1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

