    apply (lap_of_run tm Cc true true cho_1RB1LC_1RC1LD_1LA0RD_0LC1RD B0_1RB1LC_1RC1LD_1LA0RD_0LC1RD B1_1RB1LC_1RC1LD_1LA0RD_0LC1RD 4 12 p j' [] []).
