  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_1RC1LD_1LA0RD_0LC1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_1RC1LD_1LA0RD_0LC1RD p j E)].
